// Broadcast resource used by the site UI.
// Ref: #/components/schemas/SiteBroadcastResource
type SiteBroadcastResource struct {
	// Unique identifier.
	ID EntityId `json:"id"`
	// Internal broadcast name.
	Name string `json:"name"`
	// Email subject line.
	Subject string `json:"subject"`
	// Sender display name (defaults to the integration's).
	FromName OptNilString `json:"fromName"`
	// Sender email address (defaults to the integration's).
	FromEmail OptNilEmailAddress `json:"fromEmail"`
	// HTML body with Liquid merge tags.
	Body string `json:"body"`
	// The editor's JSON document the body was built from; null when the body was written as HTML.
	Doc OptNilEditorDocument `json:"doc"`
	// Version of the editor that rendered the document; null with it.
	EditorVersion OptNilString `json:"editorVersion"`
	// Warnings of the lint over the stored content (ADR 0040); set on the response of a save, never blocks
	// it.
	Warnings []LintFinding `json:"warnings"`
	// Target segment; null means all contacts. Once the broadcast leaves draft it holds a copy of the
	// segment's condition taken then, and this names the segment only as where its audience came from.
	SegmentId OptNilEntityId `json:"segmentId"`
	// Sending integration; null means the workspace default.
	IntegrationId OptNilEntityId `json:"integrationId"`
	// Lifecycle status.
	Status SiteBroadcastStatus `json:"status"`
	// Why sending is currently held, when it is: `workspace_suspended`, `unverified_domain`,
	// `no_integration` or `provider_stopped` (the provider has stopped the account). A hold is reversible
	// and not a failure: the broadcast keeps its status and the remaining recipients send once it lifts.
	HoldReason OptNilString `json:"holdReason"`
	// When the broadcast is scheduled to send.
	ScheduledAt OptNilTimestamp `json:"scheduledAt"`
	// When the broadcast finished sending.
	SentAt OptNilTimestamp `json:"sentAt"`
	// Delivery counters.
	Stats SiteBroadcastStats `json:"stats"`
	// Progress and ETA while the broadcast is sending; null otherwise. Returned by get and send only,
	// never by the list.
	Progress OptNilSiteBroadcastProgress `json:"progress"`
	// When the broadcast was archived; null while it is kept. Only a sent or failed broadcast is archived.
	ArchivedAt OptNilTimestamp `json:"archivedAt"`
	// Creation timestamp.
	CreatedAt Timestamp `json:"createdAt"`
	// Last update timestamp.
	UpdatedAt Timestamp `json:"updatedAt"`
}

