// Workspace the current user belongs to.
// Ref: #/components/schemas/SiteWorkspaceResource
type SiteWorkspaceResource struct {
	// The Workspace id: its short opaque public address and the route key for nested workspace resources
	// (ADR 0043).
	ID WorkspaceId `json:"id"`
	// Display name.
	Name string `json:"name"`
	// Per-workspace collect write-key (x-collect-key) for the tracking snippet.
	CollectKey string `json:"collectKey"`
	// Physical postal address printed in the marketing email footer (CAN-SPAM 15 U.S.C. §7704(a)(5)).
	// Empty until the workspace sets one.
	PostalAddress string `json:"postalAddress"`
	// The Workspace time zone (ADR 0057): the IANA name every analytics report counts its days in. UTC
	// until an Owner or Admin sets it.
	Timezone TimeZoneName `json:"timezone"`
	// The authenticated User's role in this Workspace (from their Membership). It rides the Workspace list
	// so role-gated UI is known even while the Workspace's own endpoints are withheld under a Two-factor
	// requirement.
	Role SiteMembershipRole `json:"role"`
	// The Permissions the authenticated User's Role holds in this Workspace (ADR 0061): the client asks
	// these whether to offer an action, it never computes them from the Role.
	Permissions []Permission `json:"permissions"`
	// When outbound sending was suspended (ADR 0007); absent while the workspace can send. A suspension
	// freezes every send surface but not login, reads or tracking.
	SuspendedAt OptNilTimestamp `json:"suspendedAt"`
	// Why sending was suspended, shown to the owner; present only while suspended.
	SuspensionReason OptNilString `json:"suspensionReason"`
	// Where to appeal a suspension by email (SPHERICON_SUPPORT_EMAIL); absent when the instance configured
	// none.
	SupportEmail OptNilString `json:"supportEmail"`
	// The public origin an AI agent connects to as `<mcpUrl>/mcp`: SPHERICON_MCP_URL when MCP has its own
	// host, otherwise the app origin.
	McpUrl string `json:"mcpUrl"`
	// The public origin the tracker snippet loads `/t.js` from and posts `/collect` to:
	// SPHERICON_TRACKER_URL when the tracker has its own host, otherwise the app origin.
	TrackerUrl string `json:"trackerUrl"`
	// The Staff holds active now, oldest key first; empty while nothing holds sending. Any one freezes
	// every send surface, like a suspension, but a lapsed hold is never listed.
	Holds []SiteWorkspaceHold `json:"holds"`
	// When an Owner or Admin switched on the Two-factor requirement (ADR 0020); absent while every member
	// may work without a Second factor.
	SecondFactorRequiredAt OptNilTimestamp `json:"secondFactorRequiredAt"`
	// When the authenticated User's grace under the Two-factor requirement ends: 7 days after the later of
	// the requirement's start and their Membership's creation. Absent without a requirement or once the
	// User has a Second factor. After it, every request to this Workspace answers 403 with code
	// second_factor_required until the User enrolls one.
	SecondFactorGraceEndsAt OptNilTimestamp `json:"secondFactorGraceEndsAt"`
	// The Send cap the platform set on the Workspace, with its sends over the last 24 hours; null when no
	// Send cap applies. Read-only: no operation lets the Workspace change it.
	SendCap OptNilSiteSendCap `json:"sendCap"`
	// Whether the authenticated User may open the Account link: true only for an Owner, and only on an
	// installation configured for it.
	AccountLinkAvailable bool `json:"accountLinkAvailable"`
	// Creation timestamp.
	CreatedAt Timestamp `json:"createdAt"`
}

